"use strict";
// Reads its own package's files at load: guarded inputs (the build records
// their size and mtime as boot guards), so the load still defers.
const fs = require("fs");
const path = require("path");

const dataFile = path.join(__dirname, "data.txt");
const greeting = fs.existsSync(dataFile) ? fs.readFileSync(dataFile, "utf8").trim() : "missing";
const version = JSON.parse(fs.readFileSync(path.join(__dirname, "package.json"), "utf8")).version;

function greet(who) {
  return `${greeting}, ${who} (v${version})`;
}
module.exports = { greet };
